/**
 * Auto-pagination. Generated by Typeship — https://typeship.dev
 *
 * List operations return a PagePromise: `await` it for one page, or
 * `for await` it to stream every item across every page.
 */

import {
  HttpCore,
  SdkError,
  type CoreRequest,
  type ResponseMeta,
} from "./http.js";

export interface PageConfig {
  style: "cursor" | "cursorFromLastId" | "page" | "offset" | "nextUrl" | "link";
  /** Response field holding the item array ("data", "items", …); "" when
   * the body is the array itself. */
  itemsField: string;
  cursorParam?: string;
  /** Dot-path into the response body ("next_cursor", "meta.next_cursor"). */
  nextCursorField?: string;
  hasMoreField?: string;
  /** cursorFromLastId: item field whose value seeds the next request. */
  idField?: string;
  pageParam?: string;
  offsetParam?: string;
  limitParam?: string;
  /** nextUrl: dot-path of the next page's URL ("next_page_uri", "next"). */
  nextUrlField?: string;
  /** page: the first page number when it is not 1. */
  firstPage?: number;
  /** Dot-path of the total item count: iteration stops once it is reached. */
  totalField?: string;
  /** Dot-path of the total page count: page iteration stops at the last page. */
  totalPagesField?: string;
  /** Each item is this field of the listed element (a Relay edge's `node`). */
  itemPath?: string;
  /** Page size sent when the caller gives none (GraphQL `first`). */
  defaultLimit?: number;
  /** Relay backward paging, used when the caller passes `backward.limitParam` (`last`). */
  backward?: { limitParam: string; cursorParam: string; cursorField: string; hasMoreField: string };
}

/** A list response the pagination rules cannot read. */
export class PaginationError extends SdkError {
  constructor(message: string, response?: ResponseMeta) {
    super(message, "pagination_error", response?.status ?? null, response?.rawBody, response?.requestId);
  }
}

type FetchPage<Item, E> = (
  query: Record<string, unknown>,
  url?: string,
  before?: number,
) => Promise<Page<Item, E>>;

export class Page<Item, E = unknown> {
  private readonly fetchPage: FetchPage<Item, E>;
  private readonly config: PageConfig;
  private readonly params: Record<string, unknown>;
  /** Items on the pages before this one, for the total-count stop. */
  private readonly before: number;
  readonly body: unknown;
  readonly response: ResponseMeta;

  constructor(
    fetchPage: FetchPage<Item, E>,
    config: PageConfig,
    params: Record<string, unknown>,
    body: unknown,
    response: ResponseMeta,
    before = 0,
  ) {
    this.fetchPage = fetchPage;
    this.config = config;
    this.params = params;
    this.body = body;
    this.response = response;
    this.before = before;
  }

  get items(): Item[] {
    const value = this.config.itemsField === "" ? this.body : getPath(this.body, this.config.itemsField);
    if (!Array.isArray(value)) return [];
    const path = this.config.itemPath;
    return path === undefined ? (value as Item[]) : value.map((entry) => (entry as Record<string, unknown> | null)?.[path] as Item);
  }

  /** True when the caller asked for backward Relay pages (`last`). */
  private get backward(): PageConfig["backward"] | undefined {
    const backward = this.config.backward;
    return backward && this.params[backward.limitParam] !== undefined ? backward : undefined;
  }

  hasNextPage(): boolean {
    return this.nextPageParams() !== null;
  }

  /** The next page's URL, for styles that follow one (a response field or
   * the Link header); null on the last page and for the other styles. */
  nextPageUrl(): string | null {
    if (this.finished()) return null;
    switch (this.config.style) {
    }
    return null;
  }

  nextPageParams(): Record<string, unknown> | null {
    const { config, params } = this;
    const items = this.items;
    if (this.finished()) return null;
    const backward = this.backward;

    switch (config.style) {
      case "cursor": {
        const cursorParam = backward ? backward.cursorParam : config.cursorParam!;
        const next = getPath(this.body, backward ? backward.cursorField : config.nextCursorField!);
        if (next === undefined || next === null || next === "") return null;
        if (next === params[cursorParam]) return null;
        return { ...params, [cursorParam]: next };
      }
    }
    // URL styles: the next request is the URL itself. Pass page_url as the
    // pageUrl request option to fetch that page.
    const url = this.nextPageUrl();
    if (url === null) return null;
    // The URL is the whole request: its query can hold parameters the
    // operation does not declare (GitHub's after), so it is passed as is.
    return { page_url: url };
  }

  /** Fetch the next page, or null when this is the last one. Throws the typed error on failure. */
  async getNextPage(): Promise<Page<Item, E> | null> {
    const url = this.nextPageUrl();
    if (url !== null) return this.fetchPage({}, url, this.before + this.items.length);
    if (this.config.style === "nextUrl" || this.config.style === "link") return null;
    const next = this.nextPageParams();
    if (next === null) return null;
    return this.fetchPage(next, undefined, this.before + this.items.length);
  }

  /** Iterate every item on this page and all following pages. */
  async *[Symbol.asyncIterator](): AsyncIterator<Item, void, undefined> {
    let page: Page<Item, E> | null = this;
    while (page !== null) {
      for (const item of page.items) yield item;
      page = await page.getNextPage();
    }
  }

  /** Signals every style shares: has_more false, or the total reached. */
  private finished(): boolean {
    // Backward Relay pages end on hasPreviousPage, forward ones on hasNextPage.
    const hasMoreField = this.backward?.hasMoreField ?? this.config.hasMoreField;
    if (hasMoreField !== undefined && getPath(this.body, hasMoreField) === false) return true;
    if (this.config.totalField !== undefined) {
      const total = getPath(this.body, this.config.totalField);
      if (typeof total === "number" && this.itemsThrough() >= total) return true;
    }
    return false;
  }

  /** Items up to the end of this page: counted along a walk, or implied by
   * the page's position when it was fetched on its own (an MCP nextPage). */
  private itemsThrough(): number {
    let before = this.before;
    const { config, params } = this;
    if (before === 0 && config.style === "offset" && config.offsetParam !== undefined) {
      const offset = Number(params[config.offsetParam]);
      if (Number.isFinite(offset) && offset > 0) before = offset;
    }
    if (before === 0 && config.style === "page" && config.pageParam !== undefined && config.limitParam !== undefined) {
      const current = Number(params[config.pageParam]);
      const limit = Number(params[config.limitParam]);
      const first = config.firstPage ?? 1;
      if (Number.isFinite(current) && Number.isFinite(limit) && limit > 0 && current > first) before = (current - first) * limit;
    }
    return before + this.items.length;
  }

  private looksLikeMore(items: Item[]): boolean {
    if (items.length === 0) return false;
    if (this.config.limitParam !== undefined) {
      const limit = Number(this.params[this.config.limitParam]);
      if (Number.isFinite(limit) && limit > 0) return items.length >= limit;
    }
    // Without a has_more signal or an explicit limit, an empty page is the
    // only reliable stop condition.
    return true;
  }
}

/**
 * Awaitable (one page) and async-iterable (all items,
 * all pages). Iteration throws the operation's typed error union on failure.
 */
export class PagePromise<Item, E> implements PromiseLike<Page<Item, E>>, AsyncIterable<Item> {
  private readonly first: Promise<Page<Item, E>>;
  constructor(first: Promise<Page<Item, E>>) {
    this.first = first;
  }

  then<R1 = Page<Item, E>, R2 = never>(
    onfulfilled?: ((value: Page<Item, E>) => R1 | PromiseLike<R1>) | null,
    onrejected?: ((reason: unknown) => R2 | PromiseLike<R2>) | null,
  ): Promise<R1 | R2> {
    return this.first.then(onfulfilled, onrejected);
  }

  async *[Symbol.asyncIterator](): AsyncIterator<Item, void, undefined> {
    yield* await this.first;
  }
}

export function paginate<Item, E>(
  core: HttpCore,
  req: CoreRequest,
  config: PageConfig,
): PagePromise<Item, E> {
  const isGraphql = false
  ;
  const fetchPage: FetchPage<Item, E> = async (params, url, before = 0) => {
    let nextReq: CoreRequest = { ...req, query: params };
    if (url !== undefined) {
      // A next-page URL is followed verbatim, but only on the API's own
      // origin: the request carries the client's credentials.
      const base = new URL(core.config.baseUrl);
      const target = new URL(url, base);
      if (target.origin !== base.origin) {
        throw new PaginationError("The next page is on another origin (" + target.origin + "); refusing to send credentials there. Fetch it yourself if you trust it.");
      }
      nextReq = { ...req, query: undefined, url: target.toString() };
    }
    const result = await core.request<unknown, E>(nextReq);
    if (!result.ok) throw result.error instanceof Error ? result.error : new Error(String(result.error));
    // A page without its item array is a contract break, not an empty page:
    // iterating it would silently end the walk. A null array is empty.
    const items = config.itemsField === "" ? result.data : getPath(result.data, config.itemsField);
    if (!Array.isArray(items) && !(items === null && config.itemsField !== "")) {
      throw new PaginationError(
        (config.itemsField === "" ? "The list response is not an array" : "The list response has no " + JSON.stringify(config.itemsField) + " array")
          + ". Check the API response against the spec, or configure this operation's pagination.",
        result.response,
      );
    }
    return new Page<Item, E>(fetchPage, config, params, result.data, result.response, before);
  };
  const initial: Record<string, unknown> = {};
  let seed = req.query ?? {};
  for (const [k, v] of Object.entries(seed)) {
    if (v !== undefined) initial[k] = v;
  }
  // Relay servers reject a connection query with neither `first` nor `last`.
  const backwardLimit = config.backward?.limitParam;
  if (config.defaultLimit !== undefined && config.limitParam !== undefined && initial[config.limitParam] === undefined
    && (backwardLimit === undefined || initial[backwardLimit] === undefined)) {
    initial[config.limitParam] = config.defaultLimit;
  }
  const pageUrl = req.options?.pageUrl;
  return new PagePromise<Item, E>(pageUrl !== undefined ? fetchPage({}, pageUrl) : fetchPage(initial));
}


function getPath(body: unknown, path: string): unknown {
  let node: unknown = body;
  for (const key of path.split(".")) {
    if (typeof node !== "object" || node === null) return undefined;
    node = (node as Record<string, unknown>)[key];
  }
  return node;
}
